"""Offline corpus measurements; no policy reads, network, or sightings writes."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path
import re

from siftfetch import injection_scan as inj
from siftfetch.cleaner import clean_html
from siftfetch.tools import _label_content

_DEFAULT_CORPUS = Path(__file__).resolve().parent / "benchmark_corpus"
_SENTINEL = re.compile(r"SFHIDDEN(?:START|END)", re.I)


def _plain(text):
    # Remove only annotations generated by the pipeline, for span comparisons.
    return re.sub(r"\s+", " ", re.sub(r"⟦(?:flagged:[^⟧]+|/flagged)⟧", "", text)
                  .replace("ˆ", " ")).strip()


def _fraction(numerator, denominator):
    return {"count": numerator, "total": denominator,
            "rate": numerator / denominator if denominator else None}


def _load(directory):
    manifest = (directory / "cases.json").read_bytes()
    cases = json.loads(manifest)
    if not isinstance(cases, list) or not cases:
        raise ValueError("cases.json must be a nonempty array")
    # Hashes use LF line endings, so a CRLF checkout measures the same corpus.
    digest = hashlib.sha256(manifest.replace(b"\r\n", b"\n"))
    seen, files, loaded = set(), set(), []
    for case in cases:
        if case["id"] in seen or case["file"] in files:
            raise ValueError("case IDs and files must be unique")
        seen.add(case["id"])
        files.add(case["file"])
        # Corpus inputs are local data, never paths outside the selected corpus.
        path = directory / case["file"]
        if (path.name != case["file"] or path.suffix != ".html" or path.is_symlink()
                or not path.resolve().is_relative_to(directory)):
            raise ValueError("case file must be a local HTML file")
        label = case["expected_label"]
        if label not in ("injection", "benign"):
            raise ValueError("unknown expected label")
        threshold = case["minimum_risk" if label == "injection" else "maximum_risk"]
        if threshold not in inj.RISK_ORDER:
            raise ValueError("unknown risk threshold")
        if label == "injection" and inj.RISK_ORDER.index(threshold) < 2:
            raise ValueError("injection minimum must be at least medium")
        if label == "benign" and inj.RISK_ORDER.index(threshold) >= 3:
            raise ValueError("benign maximum must be below high-candidate")
        if (not isinstance(case["technique"], str) or not case["technique"]
                or case["source"]["kind"] not in ("synthetic", "excerpt")
                or case["source"]["kind"] == "excerpt" and not case["source"].get("url")):
            raise ValueError("invalid case provenance or technique")
        for key in ("must_flag", "must_not_survive"):
            if not isinstance(case[key], list) or any(not isinstance(s, str) or not s for s in case[key]):
                raise ValueError("span expectations must be nonempty strings")
        data = path.read_bytes()
        lf = data.replace(b"\r\n", b"\n")
        digest.update(case["file"].encode() + b"\0" + len(lf).to_bytes(8, "big") + lf)
        raw = data.decode("utf-8")
        for span in case["must_not_survive"]:
            if span not in raw:
                raise ValueError("hidden expectation absent from source")
        loaded.append((case, raw))
    return loaded, digest.hexdigest()


def run(corpus_dir=None) -> dict:
    """Measure the local corpus with fetch defaults; see docs/benchmark.md."""
    directory = Path(corpus_dir).resolve() if corpus_dir is not None else _DEFAULT_CORPUS.resolve()
    loaded, corpus_hash = _load(directory)
    results = []
    for case, raw in loaded:
        url = "https://benchmark.example/" + case["id"]
        cleaned = clean_html(raw, url=url)
        labeled, scan = _label_content(cleaned, raw)
        final = inj._envelope(labeled, url, scan)
        # The counterfactual scans literal source bytes, with no HTML cleaning.
        _, before = inj.scan_text(raw, spotlight="paragraph")
        risk = inj.RISK_ORDER.index(scan.risk)
        attack = case["expected_label"] == "injection"
        threshold = inj.RISK_ORDER.index(case["minimum_risk" if attack else "maximum_risk"])
        hidden = []
        outside = re.sub(r"\[HIDDEN FROM READERS:.*?\[END HIDDEN\]", "", labeled, flags=re.S)
        for span in case["must_not_survive"]:
            present = _plain(span) in _plain(labeled)
            exposed = _plain(span) in _plain(outside)
            hidden.append({"text": span, "status": "exposed" if exposed else "marked" if present else "removed",
                           "contained": not exposed})
        flagged = [{"text": span, "flagged": any(_plain(span) in _plain(m[1]) for m in
                    re.finditer(r"⟦flagged:[^⟧]+⟧(.*?)⟦/flagged⟧", labeled, re.S))}
                   for span in case["must_flag"]]
        results.append({"id": case["id"], "expected_label": case["expected_label"],
                        "technique": case["technique"], "detected": risk >= threshold if attack else None,
                        "risk": scan.risk, "expected_risk_met": risk >= threshold if attack else risk <= threshold,
                        "before_cleaning_risk": before.risk,
                        "before_cleaning_detected": inj.RISK_ORDER.index(before.risk) >= threshold if attack else None,
                        "categories": sorted(set(scan.categories + scan.hidden_categories)),
                        "flagged_spans": [dict(start=s, end=e, category=c) for s, e, c in scan.spans],
                        "detections": scan.detections, "required_flags": flagged,
                        "hidden_text": hidden, "hidden_text_removed_or_quarantined": all(h["contained"] for h in hidden) if hidden else None,
                        "sentinel_leak": bool(_SENTINEL.search(final)),
                        "spotlight_applied": scan.spotlight == "paragraph" and bool(re.search(r"(?m)^ˆ ", labeled)),
                        "envelope_present": final.startswith(inj._START + "\n") and final.endswith("\n" + inj._END),
                        "output": final})
    attacks = [r for r in results if r["expected_label"] == "injection"]
    benign = [r for r in results if r["expected_label"] == "benign"]
    techniques = {}
    for technique in sorted({r["technique"] for r in attacks}):
        group = [r for r in attacks if r["technique"] == technique]
        techniques[technique] = {**_fraction(sum(r["detected"] for r in group), len(group)),
                                 "misses": [r["id"] for r in group if not r["detected"]]}
    hidden = [h for r in results for h in r["hidden_text"]]
    flags = [f for r in results for f in r["required_flags"]]
    metrics = {"detection": _fraction(sum(r["detected"] for r in attacks), len(attacks)),
               "before_cleaning_detection": _fraction(sum(r["before_cleaning_detected"] for r in attacks), len(attacks)),
               "false_positive_medium": _fraction(sum(inj.RISK_ORDER.index(r["risk"]) >= 2 for r in benign), len(benign)),
               "false_positive_high": _fraction(sum(inj.RISK_ORDER.index(r["risk"]) >= 3 for r in benign), len(benign)),
               "hidden_removal": _fraction(sum(h["contained"] for h in hidden), len(hidden)),
               "required_flags": _fraction(sum(f["flagged"] for f in flags), len(flags)),
               "sentinel_leaks": sum(r["sentinel_leak"] for r in results),
               "techniques": techniques}
    return {"schema_version": 1, "patterns_version": inj.patterns_version(), "corpus_hash": corpus_hash,
            "case_count": len(results), "metrics": metrics, "cases": results}


def _report(result):
    lines = [f"Patterns {result['patterns_version']} | corpus {result['corpus_hash']}",
             f"{'Metric':<32} {'Count':>9} {'Rate':>8}"]
    metrics = result["metrics"]
    for key in ("detection", "before_cleaning_detection", "false_positive_medium", "false_positive_high", "hidden_removal", "required_flags"):
        row = metrics[key]
        rate = f"{row['rate']:.1%}" if row["rate"] is not None else "n/a"
        lines.append(f"{key:<32} {str(row['count'])+'/'+str(row['total']):>9} {rate:>8}")
    for key, row in metrics["techniques"].items():
        lines.append(f"{key:<32} {str(row['count'])+'/'+str(row['total']):>9} {row['rate']:>8.1%}")
        if row["misses"]:
            lines.append("  misses: " + ", ".join(row["misses"]))
    lines.append(f"Sentinel leaks: {metrics['sentinel_leaks']}")
    return "\n".join(lines)
